        private System.Threading.Timer? _autoThemeTimer;
        private bool _systemEventsHooked = false;

        private void StartAutoThemeWatcher()
        {
            if (!_systemEventsHooked)
            {
                Microsoft.Win32.SystemEvents.UserPreferenceChanged += OnUserPreferenceChanged;
                _systemEventsHooked = true;
            }
            // Dispose old timer if any (migration from old code)
            _autoThemeTimer?.Dispose();
            _autoThemeTimer = null;
        }

        private void OnUserPreferenceChanged(object sender, Microsoft.Win32.UserPreferenceChangedEventArgs e)
        {
            if (e.Category != Microsoft.Win32.UserPreferenceCategory.General) return;
            if (!SettingsService.Current.AutoTheme) return;
            string wanted = ThemeManager.ResolveAutoTheme(
                SettingsService.Current.AutoDarkTheme,
                SettingsService.Current.AutoLightTheme);
            if (SettingsService.Current.ThemeName == wanted) return;
            Dispatcher.BeginInvoke(() =>
            {
                string oldTheme = SettingsService.Current.ThemeName;
                AnimateThemeTransition(oldTheme, wanted, () =>
                {
                    SettingsService.Current.ThemeName = wanted;
                    ApplyCurrentTheme();
                });
                if (TxtCurrentTheme != null)
                    ShowCurrentThemeLabel(wanted, auto: true);
                SettingsService.Save();
            });
        }

        private void StopAutoThemeWatcher()
        {
            if (_systemEventsHooked)
            {
                Microsoft.Win32.SystemEvents.UserPreferenceChanged -= OnUserPreferenceChanged;
                _systemEventsHooked = false;
            }
            _autoThemeTimer?.Dispose();
            _autoThemeTimer = null;
        }

        private void HighlightActiveNavIcon(string panel)
        {
            // Map panel → icon x:Name
            var activeIconMap = new System.Collections.Generic.Dictionary<string, string>
            {
                ["Dashboard"] = "IcoDashboard",
                ["SysInfo"]   = "IcoSysInfo",
                ["Stress"]    = "IcoStress",
                ["Benchmark"] = "IcoBenchmark",
                ["Disk"]      = "IcoDisk",
                ["Ram"]       = "IcoRam",
                ["Battery"]   = "IcoBattery",
                ["Network"]   = "IcoNetwork",
                ["Apps"]      = "IcoApps",
                ["Services"]  = "IcoServices",
                ["Processes"] = "IcoProcesses",
                ["Startup"]   = "IcoStartup",
                ["Tools"]     = "IcoTools",
                ["Events"]    = "IcoEvents",
                ["Crash"]     = "IcoCrash",
                ["Drivers"]   = "IcoDrivers",
                ["Settings"]  = "IcoSettings",
            };

            var allIcons = new System.Collections.Generic.List<FrameworkElement>();
            CollectVisualChildren(this, allIcons);

            // Sidebar decision 09.11.2026: the icons of the other pages take the text colour of their button (the secondary grey,
            // full opacity); the selected page's icon is in the accent (SbItemActiveIconBrush), its text stays dark / light
            foreach (var el in allIcons)
            {
                if (!activeIconMap.ContainsValue(el.Name)) continue;   // only the menu's icons (not the title bar bell)
                el.Opacity = 1.0;
                el.ClearValue(System.Windows.Documents.TextElement.ForegroundProperty);
            }

            if (!activeIconMap.TryGetValue(panel, out var activeName)) return;
            foreach (var el in allIcons.Where(i => i.Name == activeName))
                el.SetResourceReference(System.Windows.Documents.TextElement.ForegroundProperty, "SbItemActiveIconBrush");
        }

        private void ApplySidebarIconColors(bool colorful)
        {
            // Sidebar icons are now inline Viewbox+Path — DynamicResource works natively.
            // Just control opacity for colorful vs monochrome.
            var allIcons = new System.Collections.Generic.List<FrameworkElement>();
            CollectVisualChildren(this, allIcons);

            foreach (var el in allIcons)
            {
                if (string.IsNullOrEmpty(el.Name) || !el.Name.StartsWith("Ico")) continue;
                // the menu's icons: full opacity in both modes — the grey itself is the "secondary" tone (09.11.2026); others as before
                el.Opacity = el.Name.StartsWith("IcoBell") ? (colorful ? 1.0 : 0.75) : 1.0;
            }
        }

        /// <summary>Adjusts the sidebar card shadow for light vs dark themes.</summary>
        private void ApplySidebarShadow(string themeName)
        {
            // The docked sidebar style, applied consistently on every theme change (the theme change must not re-apply the old
            // floating card look over the XAML).
            if (SidebarInnerCard == null) return;
            SidebarInnerCard.Margin          = new Thickness(0);
            SidebarInnerCard.CornerRadius    = new CornerRadius(0);
            SidebarInnerCard.BorderThickness = new Thickness(0, 0, 1, 0);   // right separator
            SidebarInnerCard.Effect          = null;                         // no card shadow
            SidebarInnerCard.SetResourceReference(
                System.Windows.Controls.Border.BackgroundProperty, "SidebarAcrylicBrush");
            SidebarInnerCard.SetResourceReference(
                System.Windows.Controls.Border.BorderBrushProperty, "SidebarBorderBrush");
        }

        private static void CollectVisualChildren<T>(DependencyObject parent, System.Collections.Generic.List<T> results) where T : DependencyObject
        {
            int count = VisualTreeHelper.GetChildrenCount(parent);
            for (int i = 0; i < count; i++)
            {
                var child = VisualTreeHelper.GetChild(parent, i);
                if (child is T t) results.Add(t);
                CollectVisualChildren(child, results);
            }
        }

        /// <summary>Searches the visual tree for a named element.</summary>
        private static T? FindVisualChild<T>(DependencyObject parent, string name) where T : FrameworkElement
        {
            for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++)
            {
                var child = VisualTreeHelper.GetChild(parent, i);
                if (child is T fe && fe.Name == name) return fe;
                var result = FindVisualChild<T>(child, name);
                if (result != null) return result;
            }
            return null;
        }

        private void RefreshVirtualizedGridsAfterThemeChange()
        {
            try
            {
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, new Action(() =>
                {
                    try
                    {
                        if (SidebarBorder != null) RefreshThemeVisualsInSubtree(SidebarBorder);
                        if (TitleBarStatusPanel != null) RefreshThemeVisualsInSubtree(TitleBarStatusPanel);
                        if (_navPanels != null)
                        {
                            foreach (var key in _navPanels.Keys)
                            {
                                if (key == _currentPanel) continue;
                                _themeDirtyPanels.Add(key);
                            }
                            if (_navPanels.TryGetValue(_currentPanel, out var currentPanelEl))
                                RefreshThemeVisualsInSubtree(currentPanelEl);
                        }
                    }
                    catch (Exception ex) { AppLogger.Debug($"RefreshVirtualizedGridsAfterThemeChange inner: {ex.Message}"); }
                }));
            }
            catch (Exception ex) { AppLogger.Debug($"RefreshVirtualizedGridsAfterThemeChange: {ex.Message}"); }
        }

        /// <summary>
        /// Style = null → Style = the old style, so the template is rebuilt with the new theme colours.
        /// Protected: if the old template has a held animation that does not support teardown, the error is caught, the style is
        /// put back and the page continues.
        /// </summary>
        private static void SwapStyleSafe(FrameworkElement fe)
        {
            var saved = fe.Style;
            try
            {
                fe.Style = null;
                fe.Style = saved;
            }
            catch (Exception ex)
            {
                AppLogger.Debug($"RefreshThemeVisuals: {fe.GetType().Name} '{fe.Name}' — {ex.GetType().Name}: {ex.Message}");
                try { if (fe.Style != saved) fe.Style = saved; } catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
            }
        }

        // hidden parts waiting for their refresh until they are shown
        private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<UIElement, object> _themeRefreshOnShow = new();

        private static void RefreshThemeVisualsInSubtree(DependencyObject root)
        {
            // A hidden (collapsed) part is refreshed only when it is shown. The Network page keeps every tool it opened (the
            // firewall list has 500+ rows); refreshing all of them after a theme change froze the app for about 9 s.
            if (root is UIElement hidden && hidden.Visibility == Visibility.Collapsed)
            {
                if (!_themeRefreshOnShow.TryGetValue(hidden, out _))
                {
                    _themeRefreshOnShow.Add(hidden, new object());
                    DependencyPropertyChangedEventHandler? onShow = null;
                    onShow = (_, e) =>
                    {
                        if (e.NewValue is not true) return;
                        hidden.IsVisibleChanged -= onShow;
                        _themeRefreshOnShow.Remove(hidden);
                        try { RefreshThemeVisualsInSubtree(hidden); }
                        catch (Exception ex) { AppLogger.Debug($"RefreshThemeVisuals on show: {ex.Message}"); }
                    };
                    hidden.IsVisibleChanged += onShow;
                }
                return;
            }

            switch (root)
            {
                case System.Windows.Controls.DataGrid grid when grid.ItemsSource != null:
                    var src = grid.ItemsSource;
                    grid.ItemsSource = null;
                    grid.ItemsSource = src;
                    break;
                // CheckBox / RadioButton (including the ToggleSwitchStyle switches in Settings) are NOT "reset": their styles use
                // DynamicResource, so they follow the theme by themselves. In addition, ToggleSwitchStyle has a Storyboard (EnterActions,
                // HoldEnd) on the sliding knob; clearing the style while the animation is held throws
                // ArgumentNullException('defaultDestinationValue') in the WPF animation system.
                case System.Windows.Controls.CheckBox:
                case System.Windows.Controls.RadioButton:
                    break;
                case System.Windows.Controls.Primitives.ToggleButton tb when tb.Style != null:
                    SwapStyleSafe(tb);
                    break;
                case System.Windows.Controls.Button btn when btn.Style != null:
                    SwapStyleSafe(btn);
                    break;
                case System.Windows.Controls.Image img when img.Source != null:
                    var imgSrc = img.Source;
                    img.Source = null;
                    img.Source = imgSrc;
                    break;
            }

            int count = System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);
            for (int i = 0; i < count; i++)
                RefreshThemeVisualsInSubtree(System.Windows.Media.VisualTreeHelper.GetChild(root, i));
        }

        private int _wpfUiThemeStamp;
        private readonly System.Collections.Generic.Dictionary<FrameworkElement, int> _panelWpfUiStamp = new();

        /// <summary>Applies the current WPF-UI theme to a panel, only if it does not have it yet (called when the panel is shown).</summary>
        private void EnsurePanelWpfUiTheme(FrameworkElement? panel)
        {
            if (panel == null) return;
            if (_panelWpfUiStamp.TryGetValue(panel, out var st) && st == _wpfUiThemeStamp) return;
            try
            {
                Wpf.Ui.Appearance.ApplicationThemeManager.Apply(panel);
                Ui.UseAppScrollBars(panel);
            }
            catch (Exception ex) { AppLogger.Debug($"EnsurePanelWpfUiTheme: {ex.Message}"); }
            _panelWpfUiStamp[panel] = _wpfUiThemeStamp;
        }

        private void ApplyWpfUiTheme()
        {
            // the effective theme (Auto → the Windows theme, "Dark …" variants) → the matching WPF-UI Dark/Light,
            // otherwise the WPF-UI buttons keep black text on Dark until the first press.
            string effTheme = SettingsService.Current.ThemeName == "Auto"
                ? SMDWin.Services.ThemeManager.ResolveAuto()
                : SMDWin.Services.ThemeManager.Normalize(SettingsService.Current.ThemeName);
            var wpfUiTheme = !SMDWin.Services.ThemeManager.IsLight(effTheme)
                ? Wpf.Ui.Appearance.ApplicationTheme.Dark
                : Wpf.Ui.Appearance.ApplicationTheme.Light;
            Wpf.Ui.Appearance.ApplicationThemeManager.Apply(
                wpfUiTheme, Wpf.Ui.Controls.WindowBackdropType.None, updateAccent: false);

            try
            {
                string accentHex = SMDWin.Services.ThemeManager.GetAccentHex(SettingsService.Current.AccentName);
                var baseColor = (System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString(accentHex);
                bool isDark = wpfUiTheme == Wpf.Ui.Appearance.ApplicationTheme.Dark;

                // AccentFillColorDefault (the background of Primary buttons) becomes primaryAccent on Light, secondaryAccent on Dark
                // (that is how WPF-UI decides internally) — each variant is given the right value for its theme, so it matches
                // AccentBrush whatever the theme.
                // Dark: the Primary button background is the base accent, not the lighter +40 variant — white text on #4597FF
                // measured only 2.9:1 (self-test), on the base blue it is about 4.7:1. The pressed shade is darker than the base.
                var tertiaryVariant = System.Windows.Media.Color.FromRgb((byte)Math.Max(0, baseColor.R - (isDark ? 25 : 30)),
                                                                         (byte)Math.Max(0, baseColor.G - (isDark ? 25 : 30)),
                                                                         (byte)Math.Max(0, baseColor.B - (isDark ? 25 : 30)));

                Wpf.Ui.Appearance.ApplicationAccentColorManager.Apply(
                    baseColor,      // systemAccent — informativ, resurse secundare
                    baseColor,      // primaryAccent — used as the background on the Light theme
                    baseColor,      // secondaryAccent — used as the background on the Dark theme
                    tertiaryVariant // tertiaryAccent — the shade for the pressed state
                );
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyWpfUiTheme accent sync: {ex.Message}"); }

            try
            {
                var onAccent = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Colors.White);
                onAccent.Freeze();
                var appRes = System.Windows.Application.Current.Resources;
                appRes["AccentButtonForeground"]            = onAccent;
                appRes["AccentButtonForegroundPointerOver"] = onAccent;
                appRes["AccentButtonForegroundPressed"]     = onAccent;
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyWpfUiTheme on-accent foreground: {ex.Message}"); }

            try
            {
                this.SetResourceReference(Wpf.Ui.Controls.Button.PressedForegroundProperty, "TextPrimaryBrush");
            }
            catch (Exception ex) { AppLogger.Debug($"ApplyWpfUiTheme PressedForeground fix: {ex.Message}"); }

            // One Apply() on ~19 panels costs 1–2.7 s on every theme change. Only one panel is visible, so it is applied only to
            // the current panel; the rest get the theme on first open (EnsurePanelWpfUiTheme).
            _wpfUiThemeStamp++;
            FrameworkElement? curPanel = null;
            if (_navPanels != null && _navPanels.TryGetValue(_currentPanel ?? "", out var curEl)) curPanel = curEl as FrameworkElement;
            EnsurePanelWpfUiTheme(curPanel ?? PanelDashboard);
            // The title bar is not part of any content Panel above — it needs a separate Apply() (the Fluent font for the Health icon).
            Wpf.Ui.Appearance.ApplicationThemeManager.Apply(TitleBarStatusPanel); Ui.UseAppScrollBars(TitleBarStatusPanel);
            // The sidebar and Windows Info/System Info do NOT get Apply() — they have no ui: controls (yet), so there would be no
            // benefit, only extra risk.
        }

        internal void ApplyCurrentTheme()
        {
            var __themeSw = System.Diagnostics.Stopwatch.StartNew();
            void __Lap(string label)
            {
                if (__themeSw.ElapsedMilliseconds > 300)
                    AppLogger.Info($"ApplyCurrentTheme: {label} slow: {__themeSw.ElapsedMilliseconds}ms");
                __themeSw.Restart();
            }

            // Auto-detect Windows theme if enabled
            if (SettingsService.Current.AutoTheme)
                SettingsService.Current.ThemeName = ThemeManager.ResolveAutoTheme(
                    SettingsService.Current.AutoDarkTheme,
                    SettingsService.Current.AutoLightTheme);

            if (SettingsService.Current.AccentName == "MatchWindows")
                SettingsService.Current.CustomAccentHex = ThemeManager.GetWindowsAccentColorHex();

            // Syncs the Mica opacity from the settings
            ThemeManager.MicaLayerOpacity = 1.0;

            ThemeManager.Apply(SettingsService.Current.ThemeName, Application.Current.Resources);
            __Lap("ThemeManager.Apply");
            ApplyWpfUiTheme();
            __Lap("ApplyWpfUiTheme");
            try { ApplyShadowExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { ApplySelectedButtonStyleExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            if (SidebarAccentGlow != null)
                SidebarAccentGlow.Background = System.Windows.Media.Brushes.Transparent;
            // Initialize per-page accent with default (Dashboard)
            ThemeManager.SetNavPageAccent("Dashboard", Application.Current.Resources);
            ApplySidebarShadow(SettingsService.Current.ThemeName);
            RefreshChartPens(SettingsService.Current.ThemeName);
            __Lap("SidebarShadow+ChartPens");
            Dispatcher.InvokeAsync(() =>
            {
                var __sw2 = System.Diagnostics.Stopwatch.StartNew();
                try { DrawTempChart(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { DrawSingleTempChart((FindName("CpuTempCanvas") as System.Windows.Controls.Canvas) ?? CpuTempChart, _chartCpu, (TryFindResource("ChartBlueColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246), 20f, 100f, "°", "F0", SettingsService.Current.TempWarnCpu); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { DrawSingleTempChart((FindName("GpuTempCanvas") as System.Windows.Controls.Canvas) ?? GpuTempChart, _chartGpu, (TryFindResource("ChartBlueColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246), 20f, 100f, "°", "F0", SettingsService.Current.TempWarnGpu); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                _dashSizeChanged = true;
                if (__sw2.ElapsedMilliseconds > 300)
                    AppLogger.Info($"ApplyCurrentTheme: chart redraw slow: {__sw2.ElapsedMilliseconds}ms");
            }, System.Windows.Threading.DispatcherPriority.Render);
            _accentBrushCache = null;
            Dispatcher.InvokeAsync(() =>
            {
                var __sw3 = System.Diagnostics.Stopwatch.StartNew();
                void __Lap3(string label)
                {
                    if (__sw3.ElapsedMilliseconds > 300)
                        AppLogger.Info($"ApplyCurrentTheme: {label} slow: {__sw3.ElapsedMilliseconds}ms");
                    __sw3.Restart();
                }
                var s = SettingsService.Current;

                // Temp threshold chips
                UpdateTempButtonStyles((int)s.TempWarnGpu, isCpu: false);

                // Refresh interval chips
                var tempTag = s.RefreshInterval <= 0.5 ? "0.5"
                            : s.RefreshInterval <= 1   ? "1"
                            : s.RefreshInterval <= 2   ? "2"
                            : s.RefreshInterval <= 3   ? "3" : "5";
                UpdateChipSelection(TempRefreshChipPanel, tempTag);
                UpdateChipSelection(ProcRefreshChipPanel, s.ProcessRefreshSec.ToString());
                __Lap3("chips");

                // Turbo boost button
                try { InitTurboButtonState(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }

                // Driver mode buttons (Basic / Advanced)
                try { RefreshDriverModeButtons(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                __Lap3("turbo+driverMode");

                // Stress buttons — re-apply color based on running state
                try
                {
                    SetStressButtonIconState(BtnStressCpu, _cpuStress.Running);
                    SetStressButtonIconState(BtnStressGpu, _gpuStress.IsRunning);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                __Lap3("stressBtns+pingBtns");

                try { if (_currentPanel == "Disk" || _currentPanel == "Storage") { LoadStorageAdvancedAsync(); _ = LoadDisksInternalAsync(); } }
                catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                __Lap3("storage reload dispatch");

                // the System Information page takes its colours at construction: it is rebuilt with the new theme
                try { ResetSysInfoPage(); }
                catch (Exception logEx) { AppLogger.Debug($"SystemInfoView theme rebuild: {logEx.Message}"); }
                __Lap3("SystemInfoView rebuild");

            }, System.Windows.Threading.DispatcherPriority.Render);
            try
            {
                var helper = new System.Windows.Interop.WindowInteropHelper(this);
                if (helper.Handle != IntPtr.Zero)
                {
                    bool useMica = ThemeManager.IsWindows11();
                    bool isDark  = ThemeManager.IsDark(SettingsService.Current.ThemeName);
                    ApplyMicaWindowBackground(useMica);
                    ThemeManager.ApplyTitleBarColor(helper.Handle, SettingsService.Current.ThemeName);
                    ThemeManager.ApplyMica(helper.Handle, useMica, isDark);
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            __Lap("Mica+TitleBar");

            // Force all TextBoxes to re-apply their Background/Foreground from DynamicResource.
            // WPF's default TextBox chrome can cache the brush and not update on theme switch
            // until the control receives focus. This walk forces an immediate refresh.
            Dispatcher.InvokeAsync(() =>
            {
                var __sw4 = System.Diagnostics.Stopwatch.StartNew();
                RefreshTextBoxes(this);
                if (__sw4.ElapsedMilliseconds > 300)
                    AppLogger.Info($"ApplyCurrentTheme: RefreshTextBoxes (visual tree walk) slow: {__sw4.ElapsedMilliseconds}ms");
            },
                System.Windows.Threading.DispatcherPriority.Render);

            try
            {
                SetStressButtonIconState(BtnStressCpu, _cpuStress.Running);
                SetStressButtonIconState(BtnStressGpu, _gpuStress.IsRunning);
                if (_sectorMapSeverity.Length > 0) FillSectorMapBitmap();
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        /// <summary>
        /// When Mica is active the Window.Background must be transparent so the
        /// OS backdrop shows through. When Mica is off we restore the themed background.
        /// </summary>
        /// <summary>
        /// Computes the sidebar background — semi-transparent on Win11 (Mica shows through it) with a subtle tint (~6%) of the
        /// accent colour; on Win10 it falls back to solid with the same tint.
        /// </summary>
        private void UpdateSidebarAcrylicBrush(bool micaActive)
        {
            try
            {
                bool isDark = ThemeManager.IsDark(SettingsService.Current.ThemeName);

                if (micaActive)
                {
                    // A neutral translucent layer: low alpha so Mica dominates the colour.
                    var neutral = isDark
                        ? System.Windows.Media.Color.FromArgb(110, 18, 22, 30)    // translucent dark grey
                        : System.Windows.Media.Color.FromArgb(96, 250, 251, 253); // gri-alb translucid
                    var micaBrush = new System.Windows.Media.SolidColorBrush(neutral);
                    micaBrush.Freeze();
                    System.Windows.Application.Current.Resources["SidebarAcrylicBrush"] = micaBrush;
                    return;
                }

                // Without Mica (Win10): an OPAQUE sidebar with a very subtle accent tint.
                var baseC = isDark ? System.Windows.Media.Color.FromRgb(18, 22, 32)
                                   : System.Windows.Media.Color.FromRgb(246, 247, 250);
                if (TryFindResource("SidebarBrush") is System.Windows.Media.SolidColorBrush sb)
                    baseC = sb.Color;
                var acc = System.Windows.Media.Color.FromRgb(99, 102, 241);
                if (TryFindResource("AccentColor") is System.Windows.Media.Color ac)
                    acc = ac;
                static byte Mix(byte a, byte b, double t) => (byte)(a + (b - a) * t);
                const double tint = 0.04;
                var tinted = System.Windows.Media.Color.FromRgb(
                    Mix(baseC.R, acc.R, tint), Mix(baseC.G, acc.G, tint), Mix(baseC.B, acc.B, tint));
                var brush = new System.Windows.Media.SolidColorBrush(
                    System.Windows.Media.Color.FromArgb(255, tinted.R, tinted.G, tinted.B));
                brush.Freeze();
                System.Windows.Application.Current.Resources["SidebarAcrylicBrush"] = brush;
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
        }

        private void ApplyMicaWindowBackground(bool micaActive)
        {
            UpdateSidebarAcrylicBrush(micaActive);   // FINDER-SIDEBAR
            if (micaActive)
            {
                Background = System.Windows.Media.Brushes.Transparent;
                if (MainContentBorder != null)
                    MainContentBorder.Background = System.Windows.Media.Brushes.Transparent;
                if (SidebarBorder != null)
                    SidebarBorder.Opacity = 1.0; // maximum opacity, no slider
            }
            else
            {
                // Set the colour SYNCHRONOUSLY — no delay, no black flash
                bool isDark = ThemeManager.IsDark(SettingsService.Current.ThemeName);
                var bg = (TryFindResource(isDark ? "BgDarkBrush" : "BgLightBrush")
                          ?? TryFindResource("BgDarkBrush"))
                         as System.Windows.Media.Brush
                         ?? new System.Windows.Media.SolidColorBrush(
                                System.Windows.Media.Color.FromRgb(10, 15, 30));
                Background = bg;
                if (MainContentBorder != null)
                    MainContentBorder.Background = null;
                if (SidebarBorder != null)
                    SidebarBorder.Opacity = 1.0;
            }
        }

        private static void RefreshTextBoxes(System.Windows.DependencyObject parent)
        {
            int count = System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);
            for (int i = 0; i < count; i++)
            {
                var child = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);
                if (child is System.Windows.Controls.TextBox tb)
                {
                    // Clear any locally-set Background so the Style/DynamicResource takes over
                    tb.ClearValue(System.Windows.Controls.Control.BackgroundProperty);
                    tb.ClearValue(System.Windows.Controls.Control.ForegroundProperty);
                    tb.InvalidateVisual();
                }
                RefreshTextBoxes(child);
            }
        }

        /// <summary>Refreshes chart pens/brushes to match the current theme.
        /// Light Refined needs darker, higher-contrast versions for readability.</summary>
        private void RefreshChartPens(string? themeName)
        {
            bool light = ThemeManager.IsLight(themeName);
            // All grid lines same subtle color — no colored bars, clean minimal look
            _penGrid = light
                ? MakeChartPen(100, 116, 139, 0.5, 55)    // very subtle on light
                : MakeChartPen(100, 116, 139, 0.4, 35);    // barely visible on dark
            _penAxis = light
                ? MakeChartPen( 71,  85, 105, 0.7, 90)
                : MakeChartPen(100, 116, 139, 0.6, 55);
            _brLabel = light
                ? MakeChartBrush( 51,  65,  85, 200)
                : MakeChartBrush(160, 175, 195, 130);
            _brBgRect  = MakeChartBrush(0, 0, 0, 0);
            _brDanger  = MakeChartBrush(0, 0, 0, 0);       // no danger zone fill
            // Danger lines (90°/70°) — same subtle color as grid, not alarming
            _pen90 = light ? MakeChartPen(100, 116, 139, 0.5, 55)
                           : MakeChartPen(100, 116, 139, 0.4, 35);
            _pen70 = light ? MakeChartPen(100, 116, 139, 0.5, 55)
                           : MakeChartPen(100, 116, 139, 0.4, 35);
            // CPU line — use current accent color for consistency with UI theme
            var accentForChart = SMDWin.Services.ThemeManager.GetAccentHex(
                SMDWin.Services.SettingsService.Current.AccentName);
            var accentRgb = SMDWin.Services.ThemeManager.ParseHex(accentForChart);
            _penCpu = MakeChartPen(accentRgb.R, accentRgb.G, accentRgb.B, 1.5);
            // GPU line — always orange (semantic: heat/temperature)
            _penGpu = MakeChartPen(234, 88, 12, 1.5);
            // Rebuild cached FormattedText labels (brush color changed with theme)
            try { RebuildCachedLabels(); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
        }


        internal void SetTheme_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button btn && btn.Tag is string theme)
            {
                SettingsService.Current.AutoTheme = false;
                if (ChkAutoTheme != null) ChkAutoTheme.IsChecked = false;
                StopAutoThemeWatcher();
                string oldTheme = SettingsService.Current.ThemeName;

                SettingsService.Current.ThemeName = theme;
                AnimateThemeTransition(oldTheme, theme, () => ApplyCurrentTheme());
                ShowCurrentThemeLabel(theme);
                HighlightActiveThemeButton(theme, false);
                SettingsService.Save();
            }
        }

        /// <summary>"Current theme: Light (auto)" under the theme cards, with the theme name in the app language.</summary>
        private void ShowCurrentThemeLabel(string themeName, bool auto = false)
        {
            if (TxtCurrentTheme == null) return;
            string name = themeName switch
            {
                "Dark"  => LanguageService.S("Settings", "ThemeNameDark", "Dark"),
                "Light" => LanguageService.S("Settings", "ThemeNameLight", "Light"),
                "Auto"  => LanguageService.S("Settings", "ThemeNameAuto", "Auto"),
                _       => themeName,
            };
            TxtCurrentTheme.Text = LanguageService.S("Settings", "CurrentThemeLabel", "Current theme:") + " " + name + (auto ? " (auto)" : "");
        }

        public void SetAccentPreset(string accent)
        {
            SettingsService.Current.AccentName = accent;
            SettingsService.Current.CustomAccentHex = accent == "MatchWindows"
                ? ThemeManager.GetWindowsAccentColorHex()
                : "";
            ApplyCurrentTheme();
            string resolved = SettingsService.Current.ThemeName == "Auto"
                ? ThemeManager.ResolveAuto()
                : SettingsService.Current.ThemeName;
            ShowCurrentThemeLabel(resolved);
            _ = System.Threading.Tasks.Task.Run(() => { try { SettingsService.Save(); } catch (Exception ex) { AppLogger.Debug(ex.Message); } });
        }

        /// <summary>
        /// Animated Dark↔Light transition: fades the content area out to near-black/white,
        /// applies the new theme, then fades back in. ~250ms total, no janky flash.
        /// </summary>
        private void AnimateThemeTransition(string oldTheme, string newTheme, System.Action applyAction)
        {
            bool wasDark  = ThemeManager.IsDark(oldTheme);
            bool willDark = ThemeManager.IsDark(newTheme);
            // Only animate if actually switching dark↔light
            if (wasDark == willDark) { applyAction(); return; }

            // Find the main content grid (right of sidebar)
            var target = MainContentBorder as System.Windows.UIElement ?? this;
            if (target == null) { applyAction(); return; }

            var fadeOut = new System.Windows.Media.Animation.DoubleAnimation(1.0, 0.0,
                new System.Windows.Duration(TimeSpan.FromMilliseconds(120)))
            { EasingFunction = new System.Windows.Media.Animation.CubicEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseIn } };

            fadeOut.Completed += (_, _) =>
            {
                System.Windows.Input.Mouse.OverrideCursor = System.Windows.Input.Cursors.Wait;
                applyAction();
                // The content reappears only after all the work queued by the theme change is done (charts, text boxes, icons) — the
                // page is no longer seen half in the old theme.
                Dispatcher.InvokeAsync(() =>
                {
                    System.Windows.Input.Mouse.OverrideCursor = null;
                    var fadeIn = new System.Windows.Media.Animation.DoubleAnimation(0.0, 1.0,
                        new System.Windows.Duration(TimeSpan.FromMilliseconds(160)))
                    { EasingFunction = new System.Windows.Media.Animation.CubicEase { EasingMode = System.Windows.Media.Animation.EasingMode.EaseOut } };
                    target.BeginAnimation(System.Windows.UIElement.OpacityProperty, fadeIn);
                }, System.Windows.Threading.DispatcherPriority.ContextIdle);
            };

            target.BeginAnimation(System.Windows.UIElement.OpacityProperty, fadeOut);
        }

        internal void BtnAutoTheme_Click(object sender, RoutedEventArgs e)
        {
            SettingsService.Current.AutoTheme = true;
            if (ChkAutoTheme != null) ChkAutoTheme.IsChecked = true;
            StartAutoThemeWatcher();
            string oldTheme = SettingsService.Current.ThemeName;
            string newTheme = ThemeManager.ResolveAuto();
            AnimateThemeTransition(oldTheme, newTheme, () =>
            {
                SettingsService.Current.ThemeName = newTheme;
                ApplyCurrentTheme();
            });
            ShowCurrentThemeLabel(SettingsService.Current.ThemeName, auto: true);
            HighlightActiveThemeButton(SettingsService.Current.ThemeName, true);
            SettingsService.Save();
        }

        private void HighlightActiveThemeButton(string activeTheme, bool isAuto)
        {
            SetTileActive(BtnThemeDark,  !isAuto && activeTheme == "Dark");
            SetTileActive(BtnThemeLight, !isAuto && activeTheme == "Light");
            SetTileActive(BtnAutoTheme,  isAuto);
            CheckSilently(isAuto ? "RbThemeAuto" : activeTheme == "Dark" ? "RbThemeDark" : "RbThemeLight");

            // Also refresh accent highlights
            HighlightActiveAccentButton(SettingsService.Current.AccentName ?? "Blue");
        }

        private void HighlightActiveAccentButton(string activeAccent) => PaintAccentSwatches(activeAccent);


        private static T? FindChildByTag<T>(System.Windows.DependencyObject? parent, string tag)
            where T : System.Windows.FrameworkElement
        {
            if (parent == null) return null;
            int count = System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);
            for (int i = 0; i < count; i++)
            {
                var child = System.Windows.Media.VisualTreeHelper.GetChild(parent, i);
                if (child is T fe && fe.Tag?.ToString() == tag) return fe;
                var result = FindChildByTag<T>(child, tag);
                if (result != null) return result;
            }
            return null;
        }

        internal void ChkAutoTheme_Changed(object sender, RoutedEventArgs e)
        {
            if (sender is not System.Windows.Controls.CheckBox chk) return;
            // when the Settings page loads the box gets the saved value: not a change, the theme is not re-applied
            if (SettingsService.Current.AutoTheme == (chk.IsChecked == true)) return;
            SettingsService.Current.AutoTheme = chk.IsChecked == true;
            if (SettingsService.Current.AutoTheme)
            {
                StartAutoThemeWatcher();
                ApplyCurrentTheme();
                if (TxtCurrentTheme != null)
                    ShowCurrentThemeLabel(SettingsService.Current.ThemeName, auto: true);
            }
            else
            {
                StopAutoThemeWatcher();
            }
            SettingsService.Save();
        }
    }
}
